  r.forms.forEach(function (f, k) {
    if (k > 0) { g.plain('+').move(x - 2, y - 9).font({ size: 16, fill: INK }); x += 20; }
    var sp = drawSpecies(g, x, y, f);
    badgeGroups.push(sp.badges);
    x += sp.w + 10;
  });
  var totalW = x - x0 - 10;
  g.plain('[').move(x0 - 16, y - 36).font({ size: 62, fill: INK, weight: 'lighter' });
  g.plain(']').move(x0 + totalW + 2, y - 36).font({ size: 62, fill: INK, weight: 'lighter' });
  g.line(plotX(r.x), plotY(pHof(Math.max(r.x, 0.001))), x0 - 20, y - 2)
    .stroke({ color: '#000', width: 0.9 });
  var nl = g.plain('net: ' + netTxt[ri]).move(x0 + totalW + 16, y - 8)
    .font({ size: 12, fill: '#555', weight: 'bold' });
  nl.hide();
  netLabels.push(nl);
  rowGroups.push(g);
});

/* ── slider marker ── */
var marker = draw.circle(11).fill('#fff').stroke({ color: MAG, width: 2.5 });
var readout = draw.plain('pH 0.10').font({ size: 12, fill: MAG, weight: 'bold' });
readout.attr({ 'paint-order': 'stroke', stroke: '#e8f3fb', 'stroke-width': 3, 'stroke-linejoin': 'round' });
marker.css('cursor', 'pointer');
marker.on('mousemove', function (e) { showTooltip('Drag the slider — this dot rides the curve', e); });
marker.on('mouseleave', hideTooltip);

function regionOf(v) { return v < 0.25 ? 0 : v < 0.75 ? 1 : v < 1.25 ? 2 : v < 1.75 ? 3 : 4; }

function update_equivalentsSlider(v) {
  var xc = Math.max(0.001, Math.min(1.999, v));
  var p = pHof(xc);
  marker.center(plotX(v), plotY(p));
  readout.text('pH ' + p.toFixed(2));
  var rx = plotX(v) + 10, ry = plotY(p) - 18;
  if (rx > px2 - 60) rx = plotX(v) - 70;
  if (ry < py12 + 6) ry = py12 + 6;
  readout.move(rx, ry);
  var act = regionOf(v);
  rowGroups.forEach(function (g, i) { g.opacity(i === act ? 1 : 0.3); });
}
function toggle_structureView(on) {
  badgeGroups.forEach(function (b) { on ? b.show() : b.hide(); });
  netLabels.forEach(function (n) { on ? n.show() : n.hide(); });
}

/* ── demo steps ── */
var steps = [
  { n: "With no base added, alanine is the fully protonated cation: ammonium (NH₃⁺) and an intact carboxylic acid (COOH), net charge +1. The curve starts low, near pH 1.", eq: 0, chg: false },
  { n: "At 0.5 equivalents the curve flattens at pH 2.34 = pKₐ1. The carboxyl group is halfway deprotonated, so the cation and the zwitterion coexist 50:50 — the first buffering region.", eq: 0.5, chg: false },
  { n: "At exactly 1.0 equivalent the curve jumps steeply through pH 6.01, the isoelectric point. The zwitterion alone dominates — note its NH₃⁺ and COO⁻ cancel to zero net charge.", eq: 1, chg: true },
  { n: "At 1.5 equivalents the second plateau sits at pH 9.69 = pKₐ2, where the ammonium group is halfway deprotonated — a 50:50 mixture of zwitterion and fully deprotonated anion.", eq: 1.5, chg: false },
  { n: "At 2.0 equivalents only the anion remains: neutral amine (NH₂, blue) and carboxylate (COO⁻), net charge −1. Drag the slider to watch the species hand off at each landmark.", eq: 2, chg: true }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  document.getElementById('equivalentsSliderInput').value = s.eq;
  document.getElementById('equivalentsSliderVal').value = s.eq;
  document.getElementById('structureViewInput').checked = s.chg;
  toggle_structureView(s.chg);
  update_equivalentsSlider(s.eq);
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Alanine's titration curve reveals its three protonation states: as hydroxide equivalents increase, the fully protonated cation loses its carboxyl proton at pKa1 to become a neutral zwitterion (dominant at the isoelectric point), then loses its ammonium proton at pKa2 to become the fully deprotonated anion.
KEY INSIGHT (what students should walk away understanding): Each plateau of the titration curve is a buffering region centered on a pKa where two protonation states coexist 50:50, while the steep midpoint at one equivalent is the isoelectric point — the pH where the zwitterion dominates and the molecule carries zero net charge.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
