// @FIGURE_CODE_BEGIN
var MAG = '#c2185b', BLU = '#1c6fc9', INK = '#333';
var frame = setPlotFrame({ xDomain: [-0.08, 4.75], yDomain: [-0.6, 12.6], margin: 46 });
var draw = frame.draw;

/* Arrowhead marker for leader lines */
var defs = draw.defs();
defs.marker(8, 8, function (m) {
  m.path('M0,0 L8,4 L0,8 z').fill('#000');
}).ref(8, 4).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse', id: 'arrh' });

function pHof(x) {
  if (x <= 0) return 0.1;
  if (x >= 2) return 12.3;
  var y = (x < 1) ? 2.34 + Math.log10(x / (1 - x)) : 9.69 + Math.log10((x - 1) / (2 - x));
  return Math.max(0.1, Math.min(12.3, y));
}

/* ── plot area: tint, grid, axes ── */
var px0 = plotX(0), px2 = plotX(2), py0 = plotY(0), py12 = plotY(12);
draw.rect(px2 - px0, py12 - py0).move(px0, py12).fill('#e8f3fb');
var i;
for (i = 0; i <= 12; i += 2) {
  draw.line(px0, plotY(i), px2, plotY(i)).stroke({ color: '#b9c6cf', width: 1 });
  draw.plain(String(i)).move(px0 - 20, plotY(i) - 7).font({ size: 11, fill: INK });
}
for (i = 0; i <= 4; i++) {
  var xv = i * 0.5;
  draw.line(plotX(xv), py0, plotX(xv), py12).stroke({ color: '#b9c6cf', width: 1 });
  draw.plain(xv.toFixed(1)).move(plotX(xv) - 10, py0 + 6).font({ size: 11, fill: INK });
}
draw.line(px0, py0, px2, py0).stroke({ color: '#000', width: 1.4 });
draw.line(px0, py0, px0, py12).stroke({ color: '#000', width: 1.4 });
draw.plain('Equivalents of HO⁻').move((px0 + px2) / 2 - 58, py0 + 22).font({ size: 13, fill: INK });
var yl = draw.plain('pH').font({ size: 13, fill: INK });
yl.move(px0 - 40, (py0 + py12) / 2 + 20).transform({ rotate: -90 });

/* ── titration curve ── */
plotFunction('titr', { fn: pHof, domain: [0.001, 1.999], samples: 700, stroke: MAG, width: 2.4 });

/* ── landmark x-markers + labels ── */
var landmarks = [
  { x: 0.5, ph: 2.34, txt: 'pKₐ1 = 2.34', lx: 0.1, ly: 3.9,
    pop: ['pKₐ1 = 2.34', 'At 0.5 equivalents the carboxyl group is half deprotonated: a 50:50 mixture of the +1 cation and the neutral zwitterion. pH = pKₐ1 — the first buffering plateau.'] },
  { x: 1.0, ph: 6.01, txt: 'Isoelectric point = 6.01', lx: 0.1, ly: 7.7,
    pop: ['Isoelectric point = 6.01', 'At exactly 1.0 equivalent the zwitterion dominates. Its NH₃⁺ and COO⁻ cancel, so the molecule carries zero net charge — this is the pI.'] },
  { x: 1.5, ph: 9.69, txt: 'pKₐ2 = 9.69', lx: 0.8, ly: 11.2,
    pop: ['pKₐ2 = 9.69', 'At 1.5 equivalents the ammonium group is half deprotonated: a 50:50 mixture of the zwitterion and the −1 anion. pH = pKₐ2 — the second buffering plateau.'] }
];
landmarks.forEach(function (L) {
  var cx = plotX(L.x), cy = plotY(L.ph);
  var g = draw.group().css('cursor', 'pointer');
  g.line(cx - 5, cy - 5, cx + 5, cy + 5).stroke({ color: '#000', width: 1.6 });
  g.line(cx - 5, cy + 5, cx + 5, cy - 5).stroke({ color: '#000', width: 1.6 });
  g.circle(16).center(cx, cy).fill('#000').opacity(0);
  var lab = g.plain(L.txt).move(plotX(L.lx), plotY(L.ly)).font({ size: 12, fill: INK, style: 'italic' });
  lab.attr({ 'paint-order': 'stroke', stroke: '#e8f3fb', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  g.on('mousemove', function (e) { showTooltip(L.txt + ' — click to snap here', e); });
  g.on('mouseleave', hideTooltip);
  g.on('click', function () {
    document.getElementById('equivalentsSliderInput').value = L.x;
    document.getElementById('equivalentsSliderVal').value = L.x;
    update_equivalentsSlider(L.x);
    showPopup(L.pop[0], L.pop[1]);
  });
});

/* ── species structures: connected formulas ──
   form 0 = cation (H₃N⁺ … COOH), 1 = zwitterion (H₃N⁺ … COO⁻), 2 = anion (H₂N … COO⁻)
   Bonds: NHx→CH, CH→CH₃ (down), CH→C (carboxyl), C=O (double, up), C→O(H)⁻  */
function drawSpecies(g, x, y, form) {
  var s = g.group();
  var nCol = (form === 2) ? BLU : MAG;
  var amTxt = (form === 2) ? 'H₂N' : 'H₃N';
  var fs = 13;

  /* atom labels */
  s.plain(amTxt).move(x, y - 7).font({ size: fs, fill: nCol, weight: 'bold' });
  if (form !== 2) s.plain('+').move(x + 21, y - 14).font({ size: 10, fill: nCol, weight: 'bold' });
  s.plain('CH').move(x + 34, y - 7).font({ size: fs, fill: INK });
  s.plain('CH₃').move(x + 34, y + 14).font({ size: fs, fill: INK });
  s.plain('C').move(x + 60, y - 7).font({ size: fs, fill: INK });
  s.plain('O').move(x + 60, y - 30).font({ size: fs, fill: INK });
  if (form === 0) {
    s.plain('OH').move(x + 74, y - 7).font({ size: fs, fill: MAG, weight: 'bold' });
  } else {
    s.plain('O').move(x + 74, y - 7).font({ size: fs, fill: MAG, weight: 'bold' });
    s.plain('−').move(x + 85, y - 14).font({ size: 11, fill: MAG, weight: 'bold' });
  }

  /* bond lines: N–CH, CH–CH₃ (vertical), CH–C, C=O (double), C–O */
  var bw = { color: INK, width: 1.2 };
  s.line(x + 30, y - 3, x + 34, y - 3).stroke(bw);            /* N—CH */
  s.line(x + 41, y + 3, x + 41, y + 13).stroke(bw);          /* CH—CH₃ down */
  s.line(x + 52, y - 3, x + 60, y - 3).stroke(bw);           /* CH—C */
  s.line(x + 63, y - 10, x + 63, y - 19).stroke(bw);         /* C=O */
  s.line(x + 67, y - 10, x + 67, y - 19).stroke(bw);         /* C=O */
  s.line(x + 69, y - 3, x + 75, y - 3).stroke(bw);           /* C—O */

  /* charge badges (net charge view) */
  var badges = s.group();
  if (form !== 2) {
    badges.circle(12).center(x + 12, y - 15).fill(nCol);
    badges.plain('+').move(x + 8.5, y - 21).font({ size: 10, fill: '#fff', weight: 'bold' });
  }
  if (form !== 0) {
    badges.circle(12).center(x + 80, y - 15).fill(MAG);
    badges.plain('−').move(x + 76.5, y - 21).font({ size: 11, fill: '#fff', weight: 'bold' });
  }
  badges.hide();
  return { group: s, badges: badges, w: 96 };
}

/* ── five rows of bracketed structures, leader arrows from curve ── */
var rows = [
  { x: 0.0, ph: 0.5, forms: [0] },
  { x: 0.5, ph: 2.34, forms: [0, 1] },
  { x: 1.0, ph: 6.01, forms: [1] },
  { x: 1.5, ph: 9.69, forms: [1, 2] },
  { x: 2.0, ph: 11.8, forms: [2] }
];
var netTxt = ['net: +1', 'net: +1 / 0', 'net: 0', 'net: 0 / −1', 'net: −1'];
var rowGroups = [], badgeGroups = [], netLabels = [], rowRects = [];

rows.forEach(function (r, ri) {
  var g = draw.group();
  var y = plotY(r.ph), x0 = plotX(2.55), x = x0;
  r.forms.forEach(function (f, k) {
    if (k > 0) { g.plain('+').move(x + 2, y - 9).font({ size: 15, fill: INK }); x += 22; }
    var sp = drawSpecies(g, x, y, f);
    badgeGroups.push(sp.badges);
    x += sp.w + 8;
  });
  var totalW = x - x0 - 8;
  g.plain('[').move(x0 - 17, y - 37).font({ size: 62, fill: INK, weight: 'lighter' });
  g.plain(']').move(x0 + totalW + 3, y - 37).font({ size: 62, fill: INK, weight: 'lighter' });
  var nl = g.plain(netTxt[ri]).move(x0 + totalW + 20, y - 8)
    .font({ size: 12, fill: '#555', weight: 'bold' });
  nl.hide();
  netLabels.push(nl);
  /* subtle highlight wash behind active row */
  var rect = draw.rect(totalW + 34, 62).move(x0 - 22, y - 36)
    .fill(MAG).opacity(0.08).attr('rx', 6);
  rect.back();
  rect.hide();
  rowRects.push(rect);
  rowGroups.push(g);
  /* leader line with arrowhead from curve point to bracket */
  var sx = plotX(r.x), sy = plotY(pHof(Math.max(r.x, 0.001)));
  draw.line(sx, sy, x0 - 22, y - 4)
    .stroke({ color: '#000', width: 0.9 })
    .attr({ 'marker-end': 'url(#arrh)' });
});

/* ── slider marker ── */
var marker = draw.circle(11).fill('#fff').stroke({ color: MAG, width: 2.5 });
var readout = draw.plain('pH 0.10').font({ size: 12, fill: MAG, weight: 'bold' });
readout.attr({ 'paint-order': 'stroke', stroke: '#e8f3fb', 'stroke-width': 3, 'stroke-linejoin': 'round' });
marker.css('cursor', 'pointer');
marker.on('mousemove', function (e) { showTooltip('Drag the slider — this dot rides the curve', e); });
marker.on('mouseleave', hideTooltip);

function regionOf(v) { return v < 0.25 ? 0 : v < 0.75 ? 1 : v < 1.25 ? 2 : v < 1.75 ? 3 : 4; }

function update_equivalentsSlider(v) {
  var xc = Math.max(0.001, Math.min(1.999, v));
  var p = pHof(xc);
  marker.center(plotX(v), plotY(p));
  readout.text('pH ' + p.toFixed(2));
  var rx = plotX(v) + 10, ry = plotY(p) - 18;
  if (rx > px2 - 60) rx = plotX(v) - 70;
  if (ry < py12 + 6) ry = py12 + 6;
  readout.move(rx, ry);
  var act = regionOf(v);
  rowRects.forEach(function (rc, i) { i === act ? rc.show() : rc.hide(); });
}
function toggle_structureView(on) {
  badgeGroups.forEach(function (b) { on ? b.show() : b.hide(); });
  netLabels.forEach(function (n) { on ? n.show() : n.hide(); });
}

/* ── demo steps ── */
var steps = [
  { n: "With no base added, alanine is the fully protonated cation: ammonium (NH₃⁺) and an intact carboxylic acid (COOH), net charge +1. The curve starts low, near pH 1.", eq: 0, chg: false },
  { n: "At 0.5 equivalents the curve flattens at pH 2.34 = pKₐ1. The carboxyl group is halfway deprotonated, so the cation and the zwitterion coexist in a 50:50 mixture — the first buffering region.", eq: 0.5, chg: false },
  { n: "At exactly 1.0 equivalent the curve jumps steeply through pH 6.01, the isoelectric point. The zwitterion alone dominates — switch to Net charge view to see its NH₃⁺ and COO⁻ cancel to zero.", eq: 1, chg: true },
  { n: "At 1.5 equivalents the second plateau sits at pH 9.69 = pKₐ2, where the ammonium group is halfway deprotonated — a 50:50 mixture of zwitterion and fully deprotonated anion.", eq: 1.5, chg: false },
  { n: "At 2.0 equivalents only the anion remains: neutral amine (NH₂, blue) and carboxylate (COO⁻), net charge −1. Drag the slider back and forth to watch the species hand off at each landmark.", eq: 2, chg: true }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  document.getElementById('equivalentsSliderInput').value = s.eq;
  document.getElementById('equivalentsSliderVal').value = s.eq;
  document.getElementById('structureViewInput').checked = s.chg;
  toggle_structureView(s.chg);
  update_equivalentsSlider(s.eq);
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

