}
draw.line(px0, py0, px2, py0).stroke({ color: '#000', width: 1.4 });
draw.line(px0, py0, px0, py12).stroke({ color: '#000', width: 1.4 });
draw.plain('Equivalents of HO⁻').move((px0 + px2) / 2 - 58, py0 + 22).font({ size: 13, fill: INK });
