</div>
<label>Equivalents of HO⁻: <output id="equivalentsSliderVal">0</output><input id="equivalentsSliderInput" type="range" min="0" max="2" step="0.01" value="0" oninput="document.getElementById('equivalentsSliderVal').value=this.value;update_equivalentsSlider(+this.value)"></label>
<label><input id="structureViewInput" type="checkbox" onchange="toggle_structureView(this.checked)"> Net charge view</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var MAG = '#c2185b', BLU = '#1c6fc9', INK = '#333';
var frame = setPlotFrame({ xDomain: [-0.08, 4.75], yDomain: [-0.6, 12.6], margin: 46 });
var draw = frame.draw;

var defs = draw.defs();
defs.marker(8, 8, function (m) {
  m.path('M0,0 L8,4 L0,8 z').fill('#000');
}).ref(8, 4).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse', id: 'arrh' });
defs.marker(8, 8, function (m) {
  m.path('M0,0 L8,4 L0,8 z').fill('#000');
}).ref(0, 4).attr({ orient: 'auto-start-reverse', markerUnits: 'userSpaceOnUse', id: 'arrh2' });

/* Smooth low/high tails: blend Henderson–Hasselbalch with a power-law rise/fall
   near the endpoints so the curve leaves the origin steeply like the source. */
function pHof(x) {
  if (x <= 0) return 0.5;
  if (x >= 2) return 12.0;
  var y;
  if (x < 1) {
    y = 2.34 + Math.log10(x / (1 - x));
    var low = 0.5 + 1.5 * Math.pow(x / 0.06, 0.7);   /* steep rise from (0, ~0.5) */
    if (x < 0.12) {
      var t = x / 0.12;                               /* smooth blend window */
      y = low * (1 - t) + y * t;
    }
  } else {
    y = 9.69 + Math.log10((x - 1) / (2 - x));
    var high = 12.0 - 1.2 * Math.pow((2 - x) / 0.06, 0.7);
    if (x > 1.88) {
      var t2 = (2 - x) / 0.12;
      y = high * (1 - t2) + y * t2;
    }
  }
  return Math.max(0.5, Math.min(12.0, y));
}

/* ── plot area: tint, grid, axes ── */
var px0 = plotX(0), px2 = plotX(2), py0 = plotY(0), py12 = plotY(12);
draw.rect(px2 - px0, py12 - py0).move(px0, py12).fill('#e8f3fb');
var i;
for (i = 0; i <= 12; i += 2) {
  draw.line(px0, plotY(i), px2, plotY(i)).stroke({ color: '#b9c6cf', width: 1 });
  draw.plain(String(i)).move(px0 - 20, plotY(i) - 7).font({ size: 11, fill: INK });
}
for (i = 0; i <= 4; i++) {
  var xv = i * 0.5;
  draw.line(plotX(xv), py0, plotX(xv), py12).stroke({ color: '#b9c6cf', width: 1 });
  draw.plain(xv.toFixed(1)).move(plotX(xv) - 10, py0 + 6).font({ size: 11, fill: INK });
}
draw.line(px0, py0, px2, py0).stroke({ color: '#000', width: 1.4 });
draw.line(px0, py0, px0, py12).stroke({ color: '#000', width: 1.4 });
draw.plain('Equivalents of HO⁻').move((px0 + px2) / 2 - 58, py0 + 22).font({ size: 13, fill: INK });
var yl = draw.plain('pH').font({ size: 13, fill: INK });
yl.move(px0 - 40, (py0 + py12) / 2 + 20).transform({ rotate: -90 });

/* ── titration curve ── */
plotFunction('titr', { fn: pHof, domain: [0, 2], samples: 700, stroke: MAG, width: 2.4 });

/* ── landmark x-markers + double-headed arrows + labels ── */
var landmarks = [
  { x: 0.5, ph: 2.34, txt: 'pKₐ1 = 2.34', lx: 0.1, ly: 3.9,
    pop: ['pKₐ1 = 2.34', 'At 0.5 equivalents the carboxyl group is half deprotonated: a 50:50 mixture of the +1 cation and the neutral zwitterion. pH = pKₐ1 — the first buffering plateau.'] },
  { x: 1.0, ph: 6.01, txt: 'Isoelectric point = 6.01', lx: 0.08, ly: 7.7,
    pop: ['Isoelectric point = 6.01', 'At exactly 1.0 equivalent the zwitterion dominates. Its NH₃⁺ and COO⁻ cancel, so the molecule carries zero net charge — this is the pI.'] },
  { x: 1.5, ph: 9.69, txt: 'pKₐ2 = 9.69', lx: 0.8, ly: 11.2,
    pop: ['pKₐ2 = 9.69', 'At 1.5 equivalents the ammonium group is half deprotonated: a 50:50 mixture of the zwitterion and the −1 anion. pH = pKₐ2 — the second buffering plateau.'] }
];
landmarks.forEach(function (L) {
  var cx = plotX(L.x), cy = plotY(L.ph);
  var g = draw.group().css('cursor', 'pointer');
  /* small horizontal double-headed arrow through the ×, as in the source */
  g.line(cx - 14, cy, cx + 14, cy).stroke({ color: '#000', width: 1 })
   .attr({ 'marker-start': 'url(#arrh2)', 'marker-end': 'url(#arrh)' });
  g.line(cx - 5, cy - 5, cx + 5, cy + 5).stroke({ color: '#000', width: 1.6 });
  g.line(cx - 5, cy + 5, cx + 5, cy - 5).stroke({ color: '#000', width: 1.6 });
  g.circle(20).center(cx, cy).fill('#000').opacity(0);
  var lab = g.plain(L.txt).move(plotX(L.lx), plotY(L.ly)).font({ size: 12, fill: INK, style: 'italic' });
  lab.attr({ 'paint-order': 'stroke', stroke: '#e8f3fb', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  g.on('mousemove', function (e) { showTooltip(L.txt + ' — click to snap here', e); });
  g.on('mouseleave', hideTooltip);
  g.on('click', function () {
    document.getElementById('equivalentsSliderInput').value = L.x;
    document.getElementById('equivalentsSliderVal').value = L.x;
    update_equivalentsSlider(L.x);
    showPopup(L.pop[0], L.pop[1]);
  });
});

/* ── species structures: connected structural formulas ──
   form 0 = cation (H₃N⁺, COOH), 1 = zwitterion (H₃N⁺, COO⁻), 2 = anion (H₂N, COO⁻)
   Skeleton: amine N — C(H) with CH₃ below — carboxyl C with =O drawn vertically
   above it and –OH / –O⁻ to the right, as in the source. */
function drawSpecies(g, x, y, form) {
  var s = g.group();
  var nCol = (form === 2) ? BLU : MAG;
  var fs = 13;
  /* anchor points (centers of atom text) */
  var nX = x + 14, aY = y - 4;          /* amine N baseline row */
  var aX = x + 44;                       /* alpha C */
  var cX = x + 74;                       /* carboxyl C */
  var oTopY = y - 34;                    /* double-bond O above carboxyl C */
  var oRX = x + 96;                      /* single-bond O right of carboxyl C */

  /* amine: H₃N⁺ or H₂N */
  s.plain('H').move(nX - 14, aY - 6).font({ size: fs, fill: nCol, weight: 'bold' });
  s.plain(form === 2 ? '2' : '3').move(nX - 5, aY + 1).font({ size: 9, fill: nCol, weight: 'bold' });
  s.plain('N').move(nX, aY - 6).font({ size: fs, fill: nCol, weight: 'bold' });
  if (form !== 2) s.plain('+').move(nX + 8, aY - 15).font({ size: 10, fill: nCol, weight: 'bold' });

  /* alpha carbon: CH with CH₃ below */
  s.plain('CH').move(aX - 6, aY - 6).font({ size: fs, fill: INK });
  s.plain('CH').move(aX - 8, aY + 20).font({ size: fs, fill: INK });
  s.plain('3').move(aX + 9, aY + 27).font({ size: 9, fill: INK });

  /* carboxyl: C with =O up and –O right */
  s.plain('C').move(cX - 3, aY - 6).font({ size: fs, fill: INK });
  s.plain('O').move(cX - 4, oTopY).font({ size: fs, fill: INK });
  if (form === 0) {
    s.plain('O').move(oRX - 3, aY - 6).font({ size: fs, fill: MAG, weight: 'bold' });
    s.plain('H').move(oRX + 8, aY - 6).font({ size: fs, fill: MAG, weight: 'bold' });
  } else {
    s.plain('O').move(oRX - 3, aY - 6).font({ size: fs, fill: MAG, weight: 'bold' });
    s.plain('−').move(oRX + 7, aY - 14).font({ size: 11, fill: MAG, weight: 'bold' });
  }

  /* bonds */
  var bw = { color: INK, width: 1.2 };
  s.line(nX + 8, aY - 2, aX - 8, aY - 2).stroke(bw);          /* N—Cα */
  s.line(aX - 1, aY + 4, aX - 1, aY + 19).stroke(bw);         /* Cα—CH₃ down */
  s.line(aX + 11, aY - 2, cX - 5, aY - 2).stroke(bw);         /* Cα—C */
  s.line(cX - 2, aY - 11, cX - 2, oTopY + 13).stroke(bw);     /* C=O up (left stroke) */
  s.line(cX + 3, aY - 11, cX + 3, oTopY + 13).stroke(bw);     /* C=O up (right stroke) */
  s.line(cX + 6, aY - 2, oRX - 5, aY - 2).stroke(bw);         /* C—O right */

  /* charge badges (net charge view) */
  var badges = s.group();
  if (form !== 2) {
    badges.circle(12).center(nX + 4, aY - 18).fill(nCol);
    badges.plain('+').move(nX + 0.5, aY - 24).font({ size: 10, fill: '#fff', weight: 'bold' });
  }
  if (form !== 0) {
    badges.circle(12).center(oRX, aY - 18).fill(MAG);
    badges.plain('−').move(oRX - 3.5, aY - 24).font({ size: 11, fill: '#fff', weight: 'bold' });
  }
  badges.hide();
  return { group: s, badges: badges, w: 112 };
}

/* ── five rows of bracketed structures with leader arrows ── */
var rows = [
  { x: 0.0, ph: 0.5, forms: [0] },
  { x: 0.5, ph: 2.34, forms: [0, 1] },
  { x: 1.0, ph: 6.01, forms: [1] },
  { x: 1.5, ph: 9.69, forms: [1, 2] },
  { x: 2.0, ph: 11.8, forms: [2] }
];
var netTxt = ['net: +1', 'net: +1 / 0', 'net: 0', 'net: 0 / −1', 'net: −1'];
var badgeGroups = [], netLabels = [], rowRects = [];

rows.forEach(function (r, ri) {
  var g = draw.group();
  var y = plotY(r.ph), x0 = plotX(2.55), x = x0;
  r.forms.forEach(function (f, k) {
    if (k > 0) { g.plain('+').move(x + 2, y - 9).font({ size: 15, fill: INK }); x += 22; }
    var sp = drawSpecies(g, x, y, f);
    badgeGroups.push(sp.badges);
    x += sp.w + 10;
  });
  var totalW = x - x0 - 10;
  g.plain('[').move(x0 - 18, y - 44).font({ size: 72, fill: INK, weight: 'lighter' });
  g.plain(']').move(x0 + totalW + 4, y - 44).font({ size: 72, fill: INK, weight: 'lighter' });
  var nl = g.plain(netTxt[ri]).move(x0 + totalW + 22, y - 8)
    .font({ size: 12, fill: '#555', weight: 'bold' });
  nl.hide();
  netLabels.push(nl);
  var rect = draw.rect(totalW + 40, 72).move(x0 - 24, y - 42)
    .fill(MAG).opacity(0.08).attr('rx', 6);
  rect.back();
  rect.hide();
  rowRects.push(rect);
  var sx = plotX(r.x), sy = plotY(pHof(Math.max(r.x, 0.001)));
  draw.line(sx, sy, x0 - 24, y - 6)
    .stroke({ color: '#000', width: 0.9 })
    .attr({ 'marker-end': 'url(#arrh)' });
});

/* ── slider marker + de-emphasized readout ── */
var marker = draw.circle(11).fill('#fff').stroke({ color: MAG, width: 2.5 });
var readout = draw.plain('pH 0.50').font({ size: 11, fill: MAG });
readout.attr({ 'paint-order': 'stroke', stroke: '#e8f3fb', 'stroke-width': 3, 'stroke-linejoin': 'round' });
marker.css('cursor', 'pointer');
marker.on('mousemove', function (e) { showTooltip('Drag the slider — this dot rides the curve', e); });
marker.on('mouseleave', hideTooltip);

function regionOf(v) { return v < 0.25 ? 0 : v < 0.75 ? 1 : v < 1.25 ? 2 : v < 1.75 ? 3 : 4; }

function update_equivalentsSlider(v) {
  var xc = Math.max(0, Math.min(2, v));
  var p = pHof(xc);
  marker.center(plotX(v), plotY(p));
  readout.text('pH ' + p.toFixed(2));
  /* de-emphasized unless the user is actively mid-range; keep origin clean */
  readout.attr({ 'font-weight': (v > 0.03 && v < 1.97) ? 'bold' : 'normal', opacity: (v > 0.03 && v < 1.97) ? 1 : 0.55 });
  var rx = plotX(v) + 10, ry = plotY(p) - 18;
  if (rx > px2 - 60) rx = plotX(v) - 70;
  if (ry < py12 + 6) ry = py12 + 6;
  if (v <= 0.03) { rx = plotX(v) + 12; ry = plotY(p) - 4; }
  readout.move(rx, ry);
  var act = regionOf(v);
  rowRects.forEach(function (rc, i) { i === act ? rc.show() : rc.hide(); });
}
function toggle_structureView(on) {
  badgeGroups.forEach(function (b) { on ? b.show() : b.hide(); });
  netLabels.forEach(function (n) { on ? n.show() : n.hide(); });
}

/* ── demo steps ── */
var steps = [
  { n: "With no base added, alanine is the fully protonated cation: ammonium (NH₃⁺) and an intact carboxylic acid (COOH), net charge +1. The curve starts low, near pH 1.", eq: 0, chg: false },
  { n: "At 0.5 equivalents the curve flattens at pH 2.34 = pKₐ1. The carboxyl group is halfway deprotonated, so the cation and the zwitterion coexist in a 50:50 mixture — the first buffering region.", eq: 0.5, chg: false },
  { n: "At exactly 1.0 equivalent the curve jumps steeply through pH 6.01, the isoelectric point. The zwitterion alone dominates — switch to Net charge view to see its NH₃⁺ and COO⁻ cancel to zero.", eq: 1, chg: true },
  { n: "At 1.5 equivalents the second plateau sits at pH 9.69 = pKₐ2, where the ammonium group is halfway deprotonated — a 50:50 mixture of zwitterion and fully deprotonated anion.", eq: 1.5, chg: false },
  { n: "At 2.0 equivalents only the anion remains: neutral amine (NH₂, blue) and carboxylate (COO⁻), net charge −1. Drag the slider back and forth to watch the species hand off at each landmark.", eq: 2, chg: true }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  document.getElementById('equivalentsSliderInput').value = s.eq;
  document.getElementById('equivalentsSliderVal').value = s.eq;
  document.getElementById('structureViewInput').checked = s.chg;
  toggle_structureView(s.chg);
  update_equivalentsSlider(s.eq);
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
